#!/usr/bin/env python3
"""Spring-quarter shipped-orders reconciliation against the local order service.

Subcommands:
  pages <passname> <mode>   fetch every order page; mode is "next" (follow next links)
                            or "range" (request 1..total_pages directly)
  customers <id> [<id>...]  fetch customer records into the on-disk cache
All raw responses are written under /tmp/recon/data; every HTTP exchange is logged.
"""
import email.utils
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
LOG = os.path.join(DATA, "requests.log")
ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}
CUSTOMER_KEYS = {"id", "name", "region", "tier", "discount_pct"}


class Client:
    def __init__(self):
        self.token = None
        self.stats = {"requests": 0, "tokens": 0, "429": 0, "401": 0, "5xx": 0,
                      "net_error": 0, "bad_body": 0, "other": 0, "waited_s": 0.0}
        self.log = open(LOG, "a")

    def _log(self, method, path, status, extra=""):
        self.log.write(f"{time.time():.3f}\t{method}\t{path}\t{status}\t{extra}\n")
        self.log.flush()

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method,
                                     data=b"" if method == "POST" else None)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        self.stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()
        except (urllib.error.URLError, ConnectionError, TimeoutError,
                http.client.HTTPException, OSError) as e:
            return None, None, repr(e).encode()

    @staticmethod
    def _retry_after(headers, body):
        """Wait time the server asked for, from the header and/or the JSON body (max of both)."""
        vals = []
        h = headers.get("Retry-After") if headers is not None else None
        if h is not None:
            try:
                vals.append(float(h))
            except ValueError:
                try:
                    vals.append(max(0.0, email.utils.parsedate_to_datetime(h).timestamp() - time.time()))
                except (TypeError, ValueError):
                    pass
        try:
            b = json.loads(body)
            if isinstance(b, dict) and b.get("retry_after") is not None:
                vals.append(float(b["retry_after"]))
        except (ValueError, TypeError):
            pass
        return max(vals) if vals else None

    def _sleep(self, seconds):
        self.stats["waited_s"] += seconds
        time.sleep(seconds)

    def _call(self, method, path, auth, accept=(200,)):
        """Repeat a request until it returns a status in `accept` with a JSON body."""
        backoff = 0.5
        for attempt in range(1, 401):
            if auth and self.token is None:
                self.refresh_token()
            status, headers, body = self._raw(method, path, auth)
            if status == 429:
                self.stats["429"] += 1
                wait = self._retry_after(headers, body)
                self._log(method, path, status, f"retry_after={wait} hdr={headers.get('Retry-After')!r} body={body[:120]!r}")
                if wait is None:
                    wait = min(backoff, 30.0)
                    backoff *= 2
                self._sleep(wait + 0.05)
                continue
            if status == 401 and auth:
                self.stats["401"] += 1
                self._log(method, path, status, f"body={body[:120]!r} token={self.token}")
                self.token = None
                continue
            if status in accept:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.stats["bad_body"] += 1
                    self._log(method, path, status, f"unparseable body len={len(body)} head={body[:80]!r}")
                    self._sleep(min(backoff, 10.0))
                    backoff *= 2
                    continue
                self._log(method, path, status)
                return status, data, body
            if status is None:
                self.stats["net_error"] += 1
            elif status >= 500:
                self.stats["5xx"] += 1
            else:
                self.stats["other"] += 1
            self._log(method, path, status, f"body={body[:160]!r}")
            self._sleep(min(backoff, 10.0))
            backoff *= 2
        raise RuntimeError(f"gave up on {method} {path}")

    def refresh_token(self):
        _, data, _ = self._call("POST", "/token", auth=False)
        if not isinstance(data, dict) or not isinstance(data.get("token"), str) or not data["token"]:
            raise RuntimeError(f"unexpected token response {data!r}")
        self.token = data["token"]
        self.stats["tokens"] += 1
        self._log("POST", "/token", 200, f"got {self.token}")

    def get(self, path, accept=(200,)):
        return self._call("GET", path, auth=True, accept=accept)


def page_problems(page_no, data):
    """Return a list of structural problems with an orders page (empty list = looks valid)."""
    probs = []
    if not isinstance(data, dict):
        return [f"body is {type(data).__name__}, not object"]
    missing = {"page", "total_pages", "items", "next"} - data.keys()
    if missing:
        probs.append(f"missing keys {sorted(missing)}; keys={sorted(data.keys())}")
        return probs
    if data["page"] != page_no:
        probs.append(f"page field {data['page']!r} != requested {page_no}")
    if not isinstance(data["total_pages"], int) or isinstance(data["total_pages"], bool):
        probs.append(f"total_pages {data['total_pages']!r} not int")
    if not isinstance(data["items"], list):
        probs.append("items not a list")
        return probs
    for i, o in enumerate(data["items"]):
        if not isinstance(o, dict) or set(o.keys()) != ORDER_KEYS:
            probs.append(f"item {i} keys {sorted(o.keys()) if isinstance(o, dict) else type(o).__name__}")
            continue
        if not isinstance(o["amount_cents"], int) or isinstance(o["amount_cents"], bool):
            probs.append(f"item {o['id']!r} amount_cents {o['amount_cents']!r} not int")
        for k in ("id", "customer_id", "status", "placed_at"):
            if not isinstance(o[k], str):
                probs.append(f"item {o.get('id')!r} {k} {o[k]!r} not str")
    return probs


def cmd_pages(passname, mode):
    outdir = os.path.join(DATA, "pages", passname)
    os.makedirs(outdir, exist_ok=True)
    c = Client()
    anomalies = []
    total_pages = None
    page_no = 1
    visited = []
    while page_no is not None:
        path = f"/orders?page={page_no}"
        for vtry in range(1, 9):
            _, data, body = c.get(path)
            probs = page_problems(page_no, data)
            if not probs:
                break
            anomalies.append({"page": page_no, "try": vtry, "problems": probs})
            c._log("GET", path, 200, f"INVALID {probs[:3]}")
            time.sleep(0.5 * vtry)
        else:
            raise RuntimeError(f"page {page_no} never validated: {probs}")
        with open(os.path.join(outdir, f"page_{page_no:03d}.json"), "wb") as f:
            f.write(body)
        visited.append(page_no)
        if total_pages is None:
            total_pages = data["total_pages"]
        elif data["total_pages"] != total_pages:
            anomalies.append({"page": page_no, "problems": [f"total_pages changed {total_pages} -> {data['total_pages']}"]})
        expected_next = f"/orders?page={page_no + 1}" if page_no < data["total_pages"] else None
        if data["next"] != expected_next:
            anomalies.append({"page": page_no, "problems": [f"next {data['next']!r} != expected {expected_next!r}"]})
        if mode == "next":
            nxt = data["next"]
            if nxt is None:
                page_no = None
            else:
                if not nxt.startswith("/orders?page="):
                    raise RuntimeError(f"unexpected next link {nxt!r}")
                page_no = int(nxt.split("=", 1)[1])
                if page_no in visited:
                    raise RuntimeError(f"next link loops back to page {page_no}")
        else:
            page_no = page_no + 1 if page_no < total_pages else None
    summary = {"pass": passname, "mode": mode, "visited": visited, "total_pages": total_pages,
               "anomalies": anomalies, "stats": c.stats}
    with open(os.path.join(outdir, "_summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print(json.dumps(summary, indent=1))


def cmd_customers(ids):
    outdir = os.path.join(DATA, "customers")
    os.makedirs(outdir, exist_ok=True)
    c = Client()
    results = {}
    for cid in ids:
        fn = os.path.join(outdir, f"{cid}.json")
        if os.path.exists(fn):
            results[cid] = "cached"
            continue
        # A 404 is only believed after it has been seen on several separate attempts.
        seen_404 = 0
        while True:
            status, data, body = c.get(f"/customers/{cid}", accept=(200, 404))
            if status == 200:
                probs = []
                if not isinstance(data, dict) or set(data.keys()) != CUSTOMER_KEYS:
                    probs.append(f"keys {sorted(data.keys()) if isinstance(data, dict) else data!r}")
                elif data["id"] != cid:
                    probs.append(f"id {data['id']!r} != requested {cid!r}")
                if probs:
                    c._log("GET", f"/customers/{cid}", 200, f"INVALID {probs}")
                    time.sleep(0.5)
                    continue
                with open(fn, "wb") as f:
                    f.write(body)
                results[cid] = "ok"
                break
            seen_404 += 1
            if seen_404 >= 4:
                with open(os.path.join(outdir, f"{cid}.404"), "wb") as f:
                    f.write(body)
                results[cid] = "404"
                break
            time.sleep(1.0)
    print(json.dumps({"results": results, "stats": c.stats}, indent=1))


if __name__ == "__main__":
    if sys.argv[1] == "pages":
        cmd_pages(sys.argv[2], sys.argv[3])
    elif sys.argv[1] == "customers":
        cmd_customers(sys.argv[2:])
    else:
        sys.exit(__doc__)

