                    data = json.loads(body)
                except ValueError:
                    self.stats["bad_body"] += 1
                    self._log(method, path, status, f"unparseable body len={len(body)} head={body[:80]!r}")
                    self._sleep(min(backoff, 10.0))
                    backoff *= 2
                    continue
                self._log(method, path, status)
                return status, data, body
            if status is None:
                self.stats["net_error"] += 1
            elif status >= 500:
                self.stats["5xx"] += 1
            else:
                self.stats["other"] += 1
            self._log(method, path, status, f"body={body[:160]!r}")
            self._sleep(min(backoff, 10.0))
            backoff *= 2
        raise RuntimeError(f"gave up on {method} {path}")

    def refresh_token(self):
        _, data, _ = self._call("POST", "/token", auth=False)
        if not isinstance(data, dict) or not isinstance(data.get("token"), str) or not data["token"]:
            raise RuntimeError(f"unexpected token response {data!r}")
        self.token = data["token"]
        self.stats["tokens"] += 1
        self._log("POST", "/token", 200, f"got {self.token}")

    def get(self, path, accept=(200,)):
        return self._call("GET", path, auth=True, accept=accept)


def page_problems(page_no, data):
    """Return a list of structural problems with an orders page (empty list = looks valid)."""
    probs = []
    if not isinstance(data, dict):
        return [f"body is {type(data).__name__}, not object"]
    missing = {"page", "total_pages", "items", "next"} - data.keys()
    if missing:
        probs.append(f"missing keys {sorted(missing)}; keys={sorted(data.keys())}")
        return probs
    if data["page"] != page_no:
        probs.append(f"page field {data['page']!r} != requested {page_no}")
    if not isinstance(data["total_pages"], int) or isinstance(data["total_pages"], bool):
        probs.append(f"total_pages {data['total_pages']!r} not int")
    if not isinstance(data["items"], list):
        probs.append("items not a list")
        return probs
    for i, o in enumerate(data["items"]):
        if not isinstance(o, dict) or set(o.keys()) != ORDER_KEYS:
            probs.append(f"item {i} keys {sorted(o.keys()) if isinstance(o, dict) else type(o).__name__}")
            continue
        if not isinstance(o["amount_cents"], int) or isinstance(o["amount_cents"], bool):
            probs.append(f"item {o['id']!r} amount_cents {o['amount_cents']!r} not int")
        for k in ("id", "customer_id", "status", "placed_at"):
            if not isinstance(o[k], str):
