    outdir = os.path.join(DATA, "pages", passname)
    os.makedirs(outdir, exist_ok=True)
    c = Client()
    anomalies = []
    total_pages = None
    page_no = 1
    visited = []
    while page_no is not None:
        path = f"/orders?page={page_no}"
        for vtry in range(1, 9):
            _, data, body = c.get(path)
            probs = page_problems(page_no, data)
