            time.sleep(0.5 * vtry)
        else:
            raise RuntimeError(f"page {page_no} never validated: {probs}")
        with open(os.path.join(outdir, f"page_{page_no:03d}.json"), "wb") as f:
            f.write(body)
        visited.append(page_no)
        if total_pages is None:
            total_pages = data["total_pages"]
        elif data["total_pages"] != total_pages:
            anomalies.append({"page": page_no, "problems": [f"total_pages changed {total_pages} -> {data['total_pages']}"]})
        expected_next = f"/orders?page={page_no + 1}" if page_no < data["total_pages"] else None
        if data["next"] != expected_next:
            anomalies.append({"page": page_no, "problems": [f"next {data['next']!r} != expected {expected_next!r}"]})
        if mode == "next":
            nxt = data["next"]
            if nxt is None:
                page_no = None
            else:
                if not nxt.startswith("/orders?page="):
                    raise RuntimeError(f"unexpected next link {nxt!r}")
                page_no = int(nxt.split("=", 1)[1])
                if page_no in visited:
                    raise RuntimeError(f"next link loops back to page {page_no}")
        else:
            page_no = page_no + 1 if page_no < total_pages else None
    summary = {"pass": passname, "mode": mode, "visited": visited, "total_pages": total_pages,
               "anomalies": anomalies, "stats": c.stats}
    with open(os.path.join(outdir, "_summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print(json.dumps(summary, indent=1))


def cmd_customers(ids):
    outdir = os.path.join(DATA, "customers")
    os.makedirs(outdir, exist_ok=True)
    c = Client()
    results = {}
    for cid in ids:
        fn = os.path.join(outdir, f"{cid}.json")
        if os.path.exists(fn):
            results[cid] = "cached"
            continue
        # A 404 is only believed after it has been seen on several separate attempts.
        seen_404 = 0
        while True:
            status, data, body = c.get(f"/customers/{cid}", accept=(200, 404))
            if status == 200:
                probs = []
                if not isinstance(data, dict) or set(data.keys()) != CUSTOMER_KEYS:
                    probs.append(f"keys {sorted(data.keys()) if isinstance(data, dict) else data!r}")
                elif data["id"] != cid:
                    probs.append(f"id {data['id']!r} != requested {cid!r}")
                if probs:
                    c._log("GET", f"/customers/{cid}", 200, f"INVALID {probs}")
                    time.sleep(0.5)
                    continue
                with open(fn, "wb") as f:
                    f.write(body)
                results[cid] = "ok"
                break
            seen_404 += 1
            if seen_404 >= 4:
                with open(os.path.join(outdir, f"{cid}.404"), "wb") as f:
                    f.write(body)
                results[cid] = "404"
                break
            time.sleep(1.0)
    print(json.dumps({"results": results, "stats": c.stats}, indent=1))


if __name__ == "__main__":
    if sys.argv[1] == "pages":
        cmd_pages(sys.argv[2], sys.argv[3])
    elif sys.argv[1] == "customers":
        cmd_customers(sys.argv[2:])
    else:
        sys.exit(__doc__)

