        if c["region"] not in REGIONS:
            raise ValueError(f"{cid}: region {c['region']!r}")
        customers[cid] = c
    by_region = {r: 0 for r in REGIONS}
    ids = set()
    for o in picked:
        assert o["amount_cents"] > 0
        c = customers[o["customer_id"]]
